function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // book
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-75, 100, 150);
  ctx.stroke();
  ctx.fill();

  // wisdom text
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Wisdom', W/2, H/2-100 + 20*Math.sin(t));

  // lesson text
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Lesson', W/2, H/2 + 20*Math.sin(t));

  // life text
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Life', W/2, H/2+100 + 20*Math.cos(t));

  // applying text
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Applying', W/2+50*Math.cos(t), H/2+50);

  // stick figure
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2-150, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-150, H/2+20);
  ctx.lineTo(W/2-150, H/2+50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-150, H/2+50);
  ctx.lineTo(W/2-120, H/2+80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-150, H/2+50);
  ctx.lineTo(W/2-180, H/2+80);
  ctx.stroke();

  // 423 text
  ctx.font = '36px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('423', W/2+150, H/2+50);

  ctx.restore();
}
